values (
  'hall-bazaar',
  '{"id":"hall-bazaar","name":"Hall Bazaar","city":"Amritsar","blurb":"Golden Temple bells, lassi steam, and a cycle-cart gone from the bazaar lane.","coverImage":"/covers/hall-bazaar.jpg","language":"pa-IN","languageLabel":"Punjabi","native":"ਪੰਜਾਬੀ","script":"Gurmukhi","premise":"Gurpreet ji''s cycle-cart, the one that carries karah prasad tins to\nthe gurdwara stalls before sangat arrives, was taken from Hall Bazaar while he\nwas in langar. Three people on this street saw a piece of what happened. In\nAmritsar nobody simply tells a stranger anything.","theme":{"sky":["#1b3b5a","#4a7fa0","#c98b4b","#e8a04f","#f0c07a"],"fog":15255672,"fogNear":62,"ground":11047016,"pavement":12166520,"plaza":13219976,"tarmac":3356219,"lane":15784080,"buildings":[16111470,13214247,13938487,11060128,15250592,14061455,13607547],"canopies":[15965202,2600544,15158332],"leaf":4025140,"trunk":5981746,"sunColour":16769184,"sunIntensity":1.4,"ambient":0.68,"hemiSky":16771264,"hemiGround":11567168,"autos":8,"cars":6,"autoCanopy":16106776,"exposure":1.14,"landmark":"delhi"},"phrases":[{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"},{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"},{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}],"npcs":[{"id":"gurpreet","name":"Gurpreet Ji","role":"Prasad Cart","speaker":"rahul","colour":15965202,"pos":[-8,-6],"provokes":"Joking about langar portions or implying he was careless.","persona":"Your cycle-cart with karah prasad tins is gone and sangat will\narrive in an hour. You are worried, not loud. If the player is respectful and\npractical you give the details: green cart PB-02-AB-9912, last seen near the\nlassi lane.","mission":{"title":"Before Sangat","brief":"Get Gurpreet to describe the cart.","successCriteria":"The player was respectful and practical and Gurpreet gave colour and identifying details.","reward":200},"clue":"Green cart, PB-02-AB-9912, near the lassi lane.","lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]},{"id":"simran","name":"Simran","role":"Lassi Stall","speaker":"neha","colour":15158332,"pos":[10,-11],"provokes":"Calling lassi ''yogurt drink'' or skipping the order.","persona":"You churn lassi by the bazaar and saw the cart leave. You won''t\ntalk to someone who won''t buy properly. Order in Punjabi politely and you say:\ntwo boys in white kurta took it toward the clock tower.","mission":{"title":"Lassi First","brief":"Order properly, then ask what she saw.","successCriteria":"The player ordered politely and Simran described the boys and direction.","reward":200},"clue":"Two boys in white kurta took it toward the clock tower.","lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]},{"id":"harjeet","name":"Harjeet","role":"Kirpan Smith","speaker":"aditya","colour":3447003,"pos":[-13,11],"provokes":"Treating the bazaar as a photo walk only.","persona":"You work metal near the bazaar. You know who has the cart because\nhe wheeled it behind your shed. You respect people who aren''t looking for a\nfight. Show you want the prasad delivered and you name Balbir at the cart shed\nbehind Hall Gate.","mission":{"title":"Not A Photo Walk","brief":"Show you want the cart back for sangat, not a scene.","successCriteria":"The player focused on the prasad delivery and Harjeet named Balbir and the shed.","reward":200},"clue":"Balbir at the cart shed behind Hall Gate has it.","requiresClues":2,"lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]},{"id":"balbir","name":"Balbir","role":"Cart Repair","speaker":"kabir","colour":2899536,"pos":[13,12],"provokes":"Calling him a thief before hearing why the cart is there.","persona":"The cart is in your shed; your nephew borrowed it to move steel\nwithout asking Gurpreet. You fix carts, you are not a thief. Separate you from\nyour nephew and offer a face-saving return before sangat, and you agree.","mission":{"title":"Nephew, Not Thief","brief":"Give Balbir a way to return the cart without shame.","successCriteria":"The player distinguished Balbir from the borrower and offered a face-saving return.","reward":400},"clue":"Cart returned with prasad tins still sealed.","requiresClues":3,"lesson":[{"npc":{"native":"ਸਤ ਸ੍ਰੀ ਅਕਾਲ","roman":"Sat sri akaal","en":"Hello"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ?","roman":"Kinne da?","en":"How much?"}},{"npc":{"native":"ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ","roman":"Mainu madad chaahidi hai","en":"I need help"},"prompt":{"native":"ਸਮਝ ਨਹੀਂ ਆਇਆ","roman":"Samjh nahin aaya","en":"I do not understand"}},{"npc":{"native":"ਹੌਲੀ ਹੌਲੀ ਦੱਸੋ","roman":"Haouli haouli daso","en":"Please say it slowly"},"prompt":{"native":"ਧੰਨਵਾਦ","roman":"Dhannvaad","en":"Thank you"}}]}],"finale":{"title":"PRASAD DELIVERED","text":"The cart is back before sangat fills the lane. Gurpreet still says nothing about the nephew."}}'::jsonb,
  '{"districtId":"hall-bazaar","finale":{"title":"HALL BAZAAR DONE","text":"Auto to the Golden Temple, lassi, karah prasad, bus to Hall Bazaar — Amritsar in Punjabi."},"tasks":[{"id":"hall-bazaar-auto","districtId":"hall-bazaar","kind":"auto","pos":[20,-4],"title":"Auto to Harmandir Sahib","brief":"Hail the auto to Sri Harmandir Sahib and agree the fare.","reward":250,"interactLabel":"Hail the auto","name":"Jasbir","role":"Auto Driver","speaker":"vijay","colour":16106776,"completionNote":"Golden Temple bound — fare settled.","lessons":{"easy":[{"npc":{"native":"ਕਿੱਥੇ ਜਾਣਾ ਹੈ?","roman":"Kitthe jaanaa hai?","en":"Where do you want to go?"},"prompt":{"native":"ਸ੍ਰੀ ਹਰਿਮੰਦਰ ਸਾਹਿਬ","roman":"Sri Harmandir Sahib","en":"Golden Temple"}},{"npc":{"native":"ਠੀਕ ਹੈ, ਕਿੰਨੇ ਦਿਓਗੇ?","roman":"Theek hai, kinne dioge?","en":"Fine, what will you pay?"},"prompt":{"native":"ਡੇਢ ਸੌ?","roman":"Dedh sau?","en":"Will you go for 150?"}},{"npc":{"native":"ਚਲੋ, ਬੈਠ ਜਾਓ","roman":"Chalo, baith jao","en":"Come on, get in"},"prompt":{"native":"ਧੰਨਵਾਦ, ਚਲੀਏ","roman":"Dhannvaad, chalie","en":"Thank you, let''s go"}}],"medium":[{"npc":{"native":"ਕਿੱਥੇ ਜਾਣਾ ਹੈ?","roman":"Kitthe jaanaa hai?","en":"Where do you want to go?"},"prompt":{"native":"ਸ੍ਰੀ ਹਰਿਮੰਦਰ ਸਾਹਿਬ","roman":"Sri Harmandir Sahib","en":"Golden Temple"}},{"npc":{"native":"ਤਿੰਨ ਸੌ! ਪੈਟਰੋਲ ਮਹਿੰਗਾ ਹੈ ਭਾਈ","roman":"Teen sau! Petrol mehnga hai bhai","en":"Three hundred! Petrol is expensive, brother"},"prompt":{"native":"ਹਾਂ ਸਮਝਿਆ, ਥੋੜਾ ਘਟਾਓ","roman":"Haan samjha, thoda ghata karo","en":"I understand, but please reduce it a bit"}},{"npc":{"native":"ਠੀਕ ਹੈ, ਦੱਸੋ","roman":"Theek hai, daso","en":"Fine, tell me"},"prompt":{"native":"ਕਿੰਨੇ ਦਾ ਹੈ?","roman":"Kinne da hai?","en":"How much is it?"}},{"npc":{"native":"ਠੀਕ ਹੈ, ਕਿੰਨੇ ਦਿਓਗੇ?","roman":"Theek hai, kinne dioge?","en":"Fine, what will you pay?"},"prompt":{"native":"ਡੇਢ ਸੌ?","roman":"Dedh sau?","en":"Will you go for 150?"}},{"npc":{"native":"ਚਲੋ, ਬੈਠ ਜਾਓ","roman":"Chalo, baith jao","en":"Come on, g